-- Pure rollback SQL; fixture users, templates, projects and tasks never persist.
begin;
create temporary table connect_test_results(message text primary key, passed boolean not null) on commit drop;
create temporary table connect_test_calls(name text primary key, project_id uuid, tasks_assigned integer, tasks_generated integer) on commit drop;
grant select, insert on connect_test_results, connect_test_calls to authenticated;
create function pg_temp.check(ok boolean, message text) returns text language plpgsql as $$
begin
  if ok is distinct from true then raise exception 'FAIL: %', message; end if;
  insert into connect_test_results values(message, true);
  return 'PASS: ' || message;
end $$;
create function pg_temp.reject(command text, expected text, message text) returns text language plpgsql as $$
declare actual text;
begin
  begin execute command; exception when others then get stacked diagnostics actual = returned_sqlstate; end;
  return pg_temp.check(actual = expected, message || coalesce(' (SQLSTATE ' || actual || ')', ' (no error)'));
end $$;
