-- Another active client's missing work must not be generated by connecting A.
insert into public.projects(id, organization_id, client_id, service_template_id, name, status, created_by) values
  ('95000000-0000-4000-8000-000000000001', '92000000-0000-4000-8000-000000000001', '97000000-0000-4000-8000-000000000002', '93000000-0000-4000-8000-000000000001', 'Client B SEO', 'active', auth.uid()),
  ('95000000-0000-4000-8000-000000000002', '92000000-0000-4000-8000-000000000001', '97000000-0000-4000-8000-000000000003', '93000000-0000-4000-8000-000000000002', 'Custom paused LSA name', 'on_hold', auth.uid());
