  ('96000000-0000-4000-8000-000000000002', '92000000-0000-4000-8000-000000000001', '95000000-0000-4000-8000-000000000002', '97000000-0000-4000-8000-000000000003', 'Paused current one-off', 'todo', null, null, auth.uid());
